// Responsive image helpers shared by Img.astro and the Markdown rehype plugin.
// The manifest is generated by packages/editor/scripts/responsive-images.mjs before every build.
import fs from 'node:fs';
import path from 'node:path';
import { cropStyle, splitPicture } from '@morphemecms/cms/lib/crop.mjs';
import { recordsIn } from '@morphemecms/cms/src/fileRecords.mjs';
import { libraryAltOf, resolveAlt } from '@morphemecms/cms/src/imageAlt.mjs';
import { config } from './siteConfig.mjs';

// The hast node type of an HTML element, as an escape: the language check reads the plain word as a Danish one.
const ELEMENT = 'el\u0065ment';
let manifest;
function load() {
  if (!manifest) {
    const file = path.resolve('src/data/image-manifest.json');
    manifest = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : {};
  }
  return manifest;
}

let records;
// The file records of the Library (src/data/files/*.json, src/fileRecords.mjs), read once per build.
function libraryRecords() {
  if (!records) {
    const folder = path.resolve(config.fileRecords ?? 'src/data/files');
    const files = fs.existsSync(folder)
      ? fs
          .readdirSync(folder)
          .filter((name) => name.endsWith('.json'))
          .map((name) => ({
            path: `${config.fileRecords ?? 'src/data/files'}/${name}`,
            oid: '',
            text: fs.readFileSync(path.join(folder, name), 'utf8'),
          }))
      : [];
    records = recordsIn(files, config.fileRecords ?? 'src/data/files');
  }
  return records;
}

/** Every image of the Library with what its record holds: its tags (`categories`), base text, decorative mark, caption and credit's name.
 * In the order of the manifest (upload folders, newest last): the "Image grid" puts them in its own order. */
export function libraryImages() {
  const records = libraryRecords();
  return Object.keys(load()).map((src) => {
    const record = records.find((stored) => stored.record.src === src)?.record;
    return {
      src,
      tags: record?.categories ?? [],
      ...(record?.alt ? { alt: record.alt } : {}),
      ...(record?.decorative ? { decorative: true } : {}),
      ...(record?.caption ? { caption: record.caption } : {}),
      ...(record?.credit ? { credit: record.credit.name } : {}),
    };
  });
}

/** What the Library says of an image (its base text, or that it is decorative), or undefined. */
export const libraryAlt = (src) => libraryAltOf(libraryRecords(), src);

/** The text an image in use is drawn with: its own (`alt`), else the Library's, else none; decorative as src/imageAlt.mjs says.
 * `{ alt, decorative }`: `alt` is "" for a decorative image or none. */
export function altFor(src, use = {}) {
  const { alt, decorative } = resolveAlt(use, libraryAlt(src));
  return { alt, decorative };
}

/** srcset, width and height for an image under /images/uploads/, or {} if unknown. */
export function responsive(src) {
  const info = load()[src];
  if (!info) return {};
  const srcset = [...info.variants.map((v) => `${v.src} ${v.w}w`), `${src} ${info.width}w`].join(', ');
  return { srcset, width: info.width, height: info.height };
}

// The sizes of an image shown `scale` times wider than its box (cut to a format, crop.mjs), e.g.
// a list like "720px, calc(100vw - 40px)" twice as wide.
const scaled = (sizes, scale) =>
  scale === 1
    ? sizes
    : sizes
        .split(',')
        .map((part) =>
          part.trim().replace(/^(\(.*\)\s+)?(.+)$/, (_, when = '', size) => `${when}calc(${size} * ${Math.round(scale * 1000) / 1000})`),
        )
        .join(', ');

/** Rehype plugin: adds srcset, sizes, width/height and lazy loading to content images, cuts an image to
 * its format (crop.mjs): in a box of that format, or itself of it without a crop, and draws a decorative
 * one with alt="". */
export function rehypeResponsiveImages({ sizes }) {
  return (tree, file) => {
    // A blog post's layout shows its featured image above the text unless the text has the same image
    // (heroImage). Then that one is the first image on screen, and every image in the text can wait.
    const featured = file?.data?.astro?.frontmatter?.image;
    const sources = [];
    const collect = (node) => {
      if (node.type === ELEMENT && node.tagName === 'img' && typeof node.properties?.src === 'string') sources.push(node.properties.src);
      node.children?.forEach(collect);
    };
    collect(tree);
    let first = !(featured && !sources.some((src) => samePicture(src, featured)));
    const visit = (node, parent, index) => {
      if (node.type === ELEMENT && node.tagName === 'img' && typeof node.properties?.src === 'string') {
        const { src, format, crop, decorative } = splitPicture(node.properties.src);
        const cut = format ? cropStyle(format, crop) : null;
        node.properties.src = src;
        // The text it has in the Markdown, else the Library's (src/imageAlt.mjs); a decorative image (crop.mjs, or the Library's)
        // is alt="" and nothing else for screen readers.
        const text = altFor(src, { alt: typeof node.properties.alt === 'string' ? node.properties.alt : '', decorative });
        if (text.alt || text.decorative) node.properties.alt = text.alt;
        if (text.decorative) delete node.properties.title;
        const { srcset, width, height } = responsive(src);
        if (srcset) {
          node.properties.srcset = srcset;
          node.properties.sizes = scaled(sizes, cut?.scale ?? 1);
          node.properties.width = width;
          node.properties.height = height;
        }
        if (first) {
          // Without a featured image the first image in the text is often the largest element on screen: load it now.
          node.properties.loading = 'eager';
          node.properties.fetchpriority = 'high';
          first = false;
        } else node.properties.loading ??= 'lazy';
        node.properties.decoding ??= 'async';
        if (cut) node.properties.style = cut.img;
        if (cut?.box && parent)
          parent.children[index] = {
            type: ELEMENT,
            tagName: 'span',
            properties: { className: ['picture-crop'], style: cut.box },
            children: [node],
          };
      }
      node.children?.forEach((child, i) => visit(child, node, i));
    };
    visit(tree);
  };
}

// WordPress keeps several versions of one image: "cropped-x-scaled-1", "x-edited", "x-e1640002824221".
// The image's own name is what is left when those additions are removed.
const imageName = (src) =>
  src
    .split('#')[0]
    .split('/')
    .pop()
    .replace(/\.\w+$/, '')
    .replace(/^cropped-/, '')
    .replace(/([-_](edited|scaled|e\d{9,}|\d))+$/g, '')
    .replace(/([-_](edited|scaled|e\d{9,}|\d))+$/g, '');
// Crops saved under a new name, so the name does not show they are the same image (the site's config).
const sameAs = config.samePictures;

/** True when two image paths show the same image. */
export function samePicture(a, b) {
  const [x, y] = [a, b].map((s) => sameAs[imageName(s)] ?? imageName(s));
  return x === y;
}

const IMAGE = /!\[[^\]]*\]\(([^)\s]+)\)/g;

// The images in the text itself, not those in the text of a block in it (a "Banner"'s, on its line of HTML).
const imagesIn = (body) => [...body.replace(/^<div data-block=.*$/gm, '').matchAll(IMAGE)].map((m) => m[1]);

/** The featured image, unless the text already shows the same image (then undefined). */
export function heroImage(image, body = '') {
  if (!image) return undefined;
  return imagesIn(body).some((src) => samePicture(src, image)) ? undefined : image;
}

/** The first image in the text, for a post without a featured image (og:image). */
export const firstImage = (body = '') => imagesIn(body)[0];

// An image's address in the text or in a block's data (its props are HTML-escaped JSON, with Markdown in
// them): a photo under /images/uploads/, without its format, crop and mark.
const PHOTO = /\/images\/uploads\/[^\s"'()\\#&;]+\.(?:webp|jpe?g|png|avif)/gi;
// Smaller than this on both sides, an image is an icon or a logo, not an image of the page.
const SMALL = 300;

/** The page's real images, in the order they are on it: in its text and in its blocks (a "Hero"'s, a
 * "Cards"'s …); photos only (no SVG or GIF), and none smaller than an icon. Each image once. */
export function picturesOf(body = '') {
  const text = body.replace(/&quot;/g, '"').replace(/&amp;/g, '&');
  const found = [...new Set(text.match(PHOTO) ?? [])];
  return found.filter((src) => {
    const { width, height } = load()[src] ?? {};
    return !(width && height && Math.max(width, height) < SMALL);
  });
}

/** The first image in a page's text, its image when it is shared (og:image, Base.astro): its address without its
 * format, crop and the mark of a decorative one, and what it shows (none for a decorative one). */
export function firstPicture(body = '') {
  const m = body.replace(/^<div data-block=.*$/gm, '').match(/!\[([^\]]*)\]\(([^)\s]+)\)/);
  if (!m) return undefined;
  const { src, decorative } = splitPicture(m[2]);
  return { src, alt: (!decorative && m[1]) || undefined };
}

/** The image shown when a page is shared (og:image): its 1200 × 630 JPEG from
 * packages/editor/scripts/responsive-images.mjs, else the image itself (without a format and crop) and no size. */
export function shareImage(address) {
  const { src } = splitPicture(address);
  const share = load()[src]?.share;
  return share ? { src: share, width: 1200, height: 630, type: 'image/jpeg' } : { src };
}
